package com.aicharacter.v3;import java.util.*;
public final class LifeDiagnostics {private LifeDiagnostics(){}public static String why(WorldState s){LifeDecision d=LifeDecisionEngine.choose(s,System.currentTimeMillis());return"Selected intention: "+d.explain()+"\nCurrent mood="+s.mood.label()+" body energy="+(int)s.body.energy+" pain="+(int)s.body.pain+" weather="+s.environment.weather;}
 public static String beliefs(WorldState s){StringBuilder out=new StringBuilder();for(Map.Entry<String,BeliefState>x:s.beliefStates.entrySet()){BeliefState b=x.getValue();out.append(x.getKey()).append(" = ").append(b.value).append(String.format(Locale.US," (%.2f)\n",b.confidence));for(BeliefEvidence e:b.evidence)out.append("  ").append(e.polarity>=0?"+":"-").append(" ").append(e.evidenceId).append(" memory=").append(e.sourceMemoryId).append(String.format(Locale.US," weight=%.2f\n",e.weight));}return out.toString();}
 public static String diary(WorldState s){if(s.diary.isEmpty())return"No grounded diary entries.";DiaryEntry d=s.diary.get(s.diary.size()-1);return d.diaryId+"\ntext="+d.text+"\nmemories="+d.sourceMemoryIds+"\nbeliefs="+d.sourceBeliefIds+"\nplaces="+d.relatedPlaceIds+"\ncreatures="+d.relatedCreatureIds;}}
